HERO_STR_STATIC(hero_str_5e464793, "` \342\200\224 two of this function's parameters are one type, so it names them the way the type does");
HERO_STR_STATIC(hero_str_5b74110c, "rename this parameter `");
HERO_STR_STATIC(hero_str_2b9cbda9, "`, or swap the two if they are in the other order \342\200\224 the two positions can end up one type, and then the names are the only thing that says which is which");
